role_css:
.suggested-action, .suggested-action:hover { background: var(--selected-background); color: var(--selected-text); font-weight: var(--type-strong-weight); }
.empty-alternative, .empty-alternative:hover { background: var(--clear); color: var(--text); text-decoration: underline; }
.library-setup .suggested-action, .writing-choice[aria-pressed="true"] { background: var(--selected-background); color: var(--selected-text); border-color: var(--clear); font-weight: var(--type-strong-weight); }
